<?php
require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/functions.php';require_once __DIR__.'/includes/csrf.php';$u=require_login();$id=(int)($_GET['trade_id']??$_POST['trade_id']??0);$s=db()->prepare("SELECT * FROM trade_requests WHERE id=? AND status='completed' AND (buyer_id=? OR seller_id=?)");$s->execute([$id,$u['id'],$u['id']]);$t=$s->fetch();if(!$t){http_response_code(403);exit('Completed trade not found.');}$target=(int)$t['buyer_id']===(int)$u['id']?(int)$t['seller_id']:(int)$t['buyer_id'];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$rating=(int)($_POST['rating']??0);if($rating<1||$rating>5){flash('error','Rating must be from 1 to 5.');}else{try{$i=db()->prepare('INSERT INTO reviews(trade_id,reviewer_id,reviewed_user_id,rating,comment) VALUES(?,?,?,?,?)');$i->execute([$id,$u['id'],$target,$rating,trim($_POST['comment']??'')]);flash('success','Review submitted.');redirect('/trade-requests.php');}catch(PDOException $e){flash('error','You already reviewed this trade.');}}}$pageTitle='Leave Review';include __DIR__.'/includes/header.php';?><form class="form-card" method="post"><h1>Leave a review</h1><?=csrf_field()?><input type="hidden" name="trade_id" value="<?=$id?>"><div class="field"><label>Rating</label><select name="rating"><?php for($i=5;$i>=1;$i--):?><option value="<?=$i?>"><?=$i?> / 5</option><?php endfor;?></select></div><div class="field"><label>Comment</label><textarea name="comment"></textarea></div><button class="btn">Submit review</button></form><?php include __DIR__.'/includes/footer.php';?>